// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// What the Graph page keeps and takes from the browser's database: the query draft of an empty graph, a newer graph
// from another tab (taken without being saved back as newer), and the canvas gestures after a data view.
const REPOSITORY_ID = uniqueRepositoryId('graph-stored-state');
const EX = 'http://example.org/stored-state/';
const DATA = `
@prefix ex: <${EX}> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice rdfs:label "Alice" ; ex:knows ex:bob , ex:dave .
ex:bob rdfs:label "Bob" ; ex:knows ex:carol .
ex:carol rdfs:label "Carol" .
ex:dave rdfs:label "Dave" .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph stored state')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, { headers: { 'Content-Type': 'text/turtle' }, data: DATA });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
});

const explorerOf = (page) => page.locator('.graph-explorer');
const node = (page, label) => explorerOf(page).locator('.graph-node')
    .filter({ has: page.locator('text', { hasText: new RegExp(`^${label}$`) }) }).first();

async function openGraph(page) {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    return explorerOf(page);
}

async function loadAll(page) {
    const explorer = await openGraph(page);
    await explorer.getByRole('button', { name: /^Load \d+ statements$/ }).click();
    await expect(node(page, 'Alice')).toBeAttached({ timeout: 30000 });
    return explorer;
}

async function setVisibility(page, state) {
    await page.evaluate((value) => {
        Object.defineProperty(document, 'visibilityState', { value, configurable: true });
        document.dispatchEvent(new Event('visibilitychange'));
    }, state);
}

/** The stored graph of this repository, as text, from the browser's database. */
function storedGraph(page) {
    return page.evaluate((repositoryId) => new Promise((resolve) => {
        const app = document.querySelector('#workbench-app');
        const serverIdentity = app?.getAttribute('data-workbench-server-identity');
        if (!app || !serverIdentity || app.getAttribute('data-workbench-repository-id') !== repositoryId) return resolve('');
        const basePath = (app.getAttribute('data-workbench-base-path') || '').replace(/\/+$/, '');
        const scope = JSON.stringify(['repository-v2', basePath, serverIdentity, repositoryId]);
        const request = indexedDB.open('graph-field-workspaces', 1);
        request.onupgradeneeded = () => request.result.createObjectStore('workspaces');
        request.onsuccess = () => {
            const read = request.result.transaction('workspaces').objectStore('workspaces').get(`workspace:${scope}`);
            read.onsuccess = () => resolve(String(read.result ?? ''));
        };
    }), REPOSITORY_ID);
}

const savedAt = (text) => /"savedAt":"([^"]+)"/.exec(text)?.[1] ?? null;

test('an empty graph keeps its query draft through a reload', async ({ page }) => {
    const explorer = await openGraph(page);
    const draft = 'SELECT ?s WHERE { ?s ?p ?o } # kept with the empty graph';
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('#sparql').fill(draft);
    await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('kept with the empty graph');

    await page.reload();
    await waitForRoute(page, 'graph');
    const reloaded = explorerOf(page);
    if (!(await reloaded.locator('#sparql').isVisible())) {
        await reloaded.getByRole('button', { name: 'Query editor', exact: true }).click();
    }
    await expect(reloaded.locator('#sparql')).toHaveValue(draft);
});

test('a Graph tab that takes the newer graph of another tab does not save it back as newer', async ({ page, context }) => {
    await loadAll(page);
    await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('Dave');
    await setVisibility(page, 'hidden');

    const other = await context.newPage();
    await other.setViewportSize({ width: 1440, height: 900 });
    await other.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(other, 'graph');
    await expect(node(other, 'Dave')).toBeAttached({ timeout: 30000 });
    await node(other, 'Dave').click();
    await explorerOf(other).getByRole('button', { name: 'Hide from the graph' }).click();
    await expect.poll(() => storedGraph(other), { timeout: 10000 }).not.toContain('"Dave"');
    const othersSave = savedAt(await storedGraph(other));
    await setVisibility(other, 'hidden');

    await setVisibility(page, 'visible');
    await expect(node(page, 'Dave')).toHaveCount(0, { timeout: 10000 });
    // Long enough for the taken graph to settle and for an autosave (800 ms) to have run.
    await page.waitForTimeout(2000);
    await setVisibility(page, 'hidden');
    await page.waitForTimeout(500);
    // Saved back with a later time, the other tab would take it as newer on its next return, and so on.
    expect(savedAt(await storedGraph(other))).toBe(othersSave);
    await other.close();
});

test('the wheel still zooms the canvas after a data view was shown', async ({ page }) => {
    await page.addInitScript(() => {
        Object.defineProperty(Navigator.prototype, 'platform', { get: () => 'Win32' });
        Object.defineProperty(Navigator.prototype, 'userAgentData', { get: () => undefined });
    });
    const explorer = await loadAll(page);
    await explorer.getByRole('tab', { name: 'Triples' }).click();
    await explorer.getByRole('tab', { name: 'Graph' }).click();
    const layer = explorer.locator('svg.graph-canvas > g').first();
    await expect(layer).toBeAttached();
    const scale = async () => Number(/scale\(([^)]+)\)/.exec((await layer.getAttribute('transform')) ?? '')?.[1]);
    await page.waitForTimeout(800); // the layout settles
    const before = await scale();
    const empty = await explorer.locator('svg.graph-canvas').evaluate((svg) => {
        const rect = svg.getBoundingClientRect();
        for (let y = rect.top + 60; y < rect.bottom - 60; y += 23) {
            for (let x = rect.left + 60; x < rect.right - 60; x += 23) {
                const around = [[0, 0], [-14, 0], [14, 0], [0, -14], [0, 14]];
                if (around.every(([dx, dy]) => document.elementFromPoint(x + dx, y + dy) === svg)) return { x, y };
            }
        }
        return null;
    });
    if (!empty) throw new Error('no empty point on the canvas');
    await page.mouse.move(empty.x, empty.y);
    await page.mouse.wheel(0, -240);
    await expect.poll(scale, { timeout: 5000 }).toBeGreaterThan(before);
});
